from csv_totals import totals

# Basic
assert totals('category,amount\na,1\nb,2\na,3\n') == {'a': 4, 'b': 2}, totals('category,amount\na,1\nb,2\na,3\n')

# Empty and header-only
assert totals('') == {}
assert totals('category,amount\n') == {}

# Quoted commas in category
assert totals('category,amount\n\"x, y\",5\n\"x, y\",2\n') == {'x, y': 7}

# Negative numbers
assert totals('category,amount\na,-5\nb,10\n') == {'a': -5, 'b': 10}

# Unicode
assert totals('category,amount\ncafé,3\n日本語,4\n') == {'café': 3, '日本語': 4}

# Invalid amount raises ValueError
try:
    totals('category,amount\na,abc\n')
    assert False, 'should have raised'
except ValueError:
    pass

try:
    totals('category,amount\na,1.5\n')
    assert False, 'should have raised'
except ValueError:
    pass

print('All checks passed')
